import { Page } from "@playwright/test";
import { BasePage } from "./BasePage";

// Generated by Tracewright from the Phase 1 page-object registry; every locator below
// was verified against the live app. Regenerate instead of editing by hand.
export class ChangePasswordPage extends BasePage {
  readonly url_pattern = "http://localhost:4000/account/password";

  constructor(page: Page) {
    super(page);
  }

  get changePasswordHeading() {
    return this.page.getByRole("heading", { name: "Change Password" });
  }

  get currentPasswordInput() {
    return this.page.getByTestId("current-password");
  }

  get newPasswordInput() {
    return this.page.getByTestId("new-password");
  }

  get confirmPasswordInput() {
    return this.page.getByTestId("confirm-password");
  }

  get changePasswordButton() {
    return this.page.getByRole("button", { name: "Change password" });
  }

  // Exists only after: "open http://localhost:4000/account/password; fill current-password with password123; fill new-password with a-long-enough-pass1; fill confirm-password with a-long-enough-pass1; click Change password"
  get passwordStatusMessage() {
    return this.page.getByRole("status");
  }

  // Exists only after: "open http://localhost:4000/account/password; fill current-password with password123; fill new-password with short; fill confirm-password with short; click Change password"
  get passwordErrorAlert() {
    return this.page.getByRole("alert");
  }
}
